/* VeriLab ChartLite: dependency-free canvas line chart, vendored with the application. MIT. */
(()=>{window.ChartLite={line:(canvas,values)=>{if(!canvas||!values?.length)return;const c=canvas.getContext('2d'),w=canvas.width=canvas.clientWidth*devicePixelRatio,h=canvas.height=canvas.clientHeight*devicePixelRatio,min=Math.min(...values),max=Math.max(...values),span=max-min||1;c.clearRect(0,0,w,h);c.strokeStyle='#176b4d';c.lineWidth=2*devicePixelRatio;c.beginPath();values.forEach((v,i)=>{const x=i*w/Math.max(1,values.length-1),y=h-(v-min)*h/span;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()}}})();
